def total(basket):
    if not basket:
        return 0

    total_price = 0
    groups_of_5 = 0
    groups_of_4 = 0
    groups_of_3 = 0
    groups_of_2 = 0
    groups_of_1 = 0

    for book in basket:
        if book in groups_of_5:
            groups_of_5 += 1
        elif book in groups_of_4:
            groups_of_4 += 1
        elif book in groups_of_3:
            groups_of_3 += 1
        elif book in groups_of_2:
            groups_of_2 += 1
        else:
            groups_of_1 += 1

    total_price += groups_of_5 * 8 * 0.75
    total_price += groups_of_4 * 8 * 0.80
    total_price += groups_of_3 * 8 * 0.90
    total_price += groups_of_2 * 8 * 0.95
    total_price += groups_of_1 * 8

    return total_price
